// FromProto populates from a protobuf message.
//
// Note: The receiver is not fully zeroed before population. Repeated and map
// fields are overwritten only when the source message has non-empty values.
// To avoid retaining stale data from a previous call, use a fresh (zero-value)
// receiver rather than reusing one across multiple FromProto calls.
func (w *WktPayload) FromProto(msg *pb.WktPayload) {
	if msg == nil {
		return
	}
	w.ID = msg.Id
	w.StructData = nil
	w.AnyValue = nil
	w.ListData = nil
	w.Mask = nil
	w.Raw = nil
	switch v := msg.GetContent().(type) {
	case *pb.WktPayload_StructData:
		if v.StructData != nil {
			m := v.StructData.AsMap()
			w.StructData = &m
		}
	case *pb.WktPayload_AnyValue:
		if v.AnyValue != nil {
			a := v.AnyValue.AsInterface()
			w.AnyValue = &a
		}
	case *pb.WktPayload_ListData:
		if v.ListData != nil {
			l := v.ListData.AsSlice()
			w.ListData = &l
		}
	case *pb.WktPayload_Mask:
		if v.Mask != nil {
			paths := make([]string, len(v.Mask.GetPaths()))
			copy(paths, v.Mask.GetPaths())
			w.Mask = &paths
		}
	case *pb.WktPayload_Raw:
		w.Raw = &v.Raw
	}
}

// ApplyFieldMaskWktPayload copies fields from src to dst based on the given paths.
//
// Only top-level field names are supported (e.g. "email", "address").
// Nested paths like "address.street" are silently ignored.
func ApplyFieldMaskWktPayload(dst, src *WktPayload, paths []string) {
	if dst == nil || src == nil {
		return
	}
	for _, path := range paths {
		switch path {
		case "id":
			dst.ID = src.ID
		case "struct_data":
			if src.StructData != nil {
				if *src.StructData == nil {
					dst.StructData = new(map[string]any)
				} else {
					copied := deepCopyValue(*src.StructData).(map[string]any)
					dst.StructData = &copied
				}
			} else {
				dst.StructData = nil
			}
		case "any_value":
			if src.AnyValue != nil {
				if *src.AnyValue == nil {
					dst.AnyValue = new(any)
				} else {
					copied := deepCopyValue(*src.AnyValue)
					dst.AnyValue = &copied
				}
			} else {
				dst.AnyValue = nil
			}
		case "list_data":
			if src.ListData != nil {
				if *src.ListData == nil {
					dst.ListData = new([]any)
				} else {
					copied := deepCopyValue(*src.ListData).([]any)
					dst.ListData = &copied
				}
			} else {
				dst.ListData = nil
			}
		case "mask":
			if src.Mask != nil {
				if *src.Mask == nil {
					dst.Mask = new([]string)
				} else {
					s := make([]string, len(*src.Mask))
					copy(s, *src.Mask)
					dst.Mask = &s
				}
			} else {
				dst.Mask = nil
			}
		case "raw":
			dst.Raw = src.Raw
		}
	}
}

// Clone returns a deep copy of WktPayload.
func (w *WktPayload) Clone() *WktPayload {
	if w == nil {
		return nil
	}
	clone := &WktPayload{
		ID: w.ID,
	}
	if w.StructData != nil {
		if *w.StructData == nil {
			clone.StructData = new(map[string]any)
		} else {
			val := deepCopyValue(*w.StructData).(map[string]any)
			clone.StructData = &val
		}
	}
	if w.AnyValue != nil {
		if *w.AnyValue == nil {
			clone.AnyValue = new(any)
		} else {
			val := deepCopyValue(*w.AnyValue)
			clone.AnyValue = &val
		}
	}
	if w.ListData != nil {
		if *w.ListData == nil {
			clone.ListData = new([]any)
		} else {
			val := deepCopyValue(*w.ListData).([]any)
			clone.ListData = &val
		}
	}
	if w.Mask != nil {
		if *w.Mask == nil {
			clone.Mask = new([]string)
		} else {
			copiedPaths := make([]string, len(*w.Mask))
			copy(copiedPaths, *w.Mask)
			clone.Mask = &copiedPaths
		}
	}
	if w.Raw != nil {
		val := *w.Raw
		clone.Raw = &val
	}
	return clone
}

// Equal reports whether w and other are equal.
func (w *WktPayload) Equal(other *WktPayload) bool {
	if w == other {
		return true
	}
	if w == nil || other == nil {
		return false
	}
	if w.ID != other.ID {
		return false
	}
	if (w.StructData == nil) != (other.StructData == nil) {
		return false
	}
	if w.StructData != nil && !reflect.DeepEqual(w.StructData, other.StructData) {
		return false
	}
	if (w.AnyValue == nil) != (other.AnyValue == nil) {
		return false
	}
	if w.AnyValue != nil && !reflect.DeepEqual(w.AnyValue, other.AnyValue) {
		return false
	}
	if (w.ListData == nil) != (other.ListData == nil) {
		return false
	}
	if w.ListData != nil && !reflect.DeepEqual(w.ListData, other.ListData) {
		return false
	}
	if (w.Mask == nil) != (other.Mask == nil) {
		return false
	}
	if w.Mask != nil && !reflect.DeepEqual(w.Mask, other.Mask) {
		return false
	}
	if (w.Raw == nil) != (other.Raw == nil) {
		return false
	}
	if w.Raw != nil && *w.Raw != *other.Raw {
		return false
	}
	return true
}

// ActiveContent returns the proto field name of the set content
// variant, or "" if none is set.
func (w *WktPayload) ActiveContent() string {
	if w == nil {
		return ""
	}
	if w.StructData != nil {
		return "struct_data"
	}
	if w.AnyValue != nil {
		return "any_value"
	}
	if w.ListData != nil {
		return "list_data"
	}
	if w.Mask != nil {
		return "mask"
	}
	if w.Raw != nil {
		return "raw"
	}
	return ""
}

// Validate checks domain invariants on WktPayload.
// It ensures at most one variant is set per oneof group.
// It also runs buf.validate constraints via protovalidate.
func (w *WktPayload) Validate() error {
	if w == nil {
		return nil
	}
	{
		_oneofCount := 0
		if w.StructData != nil {
			_oneofCount++
		}
		if w.AnyValue != nil {
			_oneofCount++
		}
		if w.ListData != nil {
			_oneofCount++
		}
		if w.Mask != nil {
			_oneofCount++
		}
		if w.Raw != nil {
			_oneofCount++
		}
		if _oneofCount > 1 {
			return fmt.Errorf("oneof content: %d variants set, expected at most 1", _oneofCount)
		}
	}
	if err := protovalidate.Validate(w.ToProto()); err != nil {
		return err
	}
	return nil
}

// deepCopyValue recursively deep-copies values that originate from structpb
// (map[string]any, []any, and scalar types like string, float64, bool, nil).
func deepCopyValue(v any) any {
	switch val := v.(type) {
	case map[string]any:
		m := make(map[string]any, len(val))
		for k, v := range val {
			m[k] = deepCopyValue(v)
		}
		return m
	case []any:
		s := make([]any, len(val))
		for i, v := range val {
			s[i] = deepCopyValue(v)
		}
		return s
	default:
		return v // scalars (string, float64, bool, nil) are immutable
	}
}
